        if (this.select_category != "all") {
          var continue_loop = 0;

          for (var loop = 0; loop < data[i].category.length; loop++) {
            if (data[i].category[loop].category_detail != null) {
              if (data[i].category[loop].category_detail.id == this.select_category || data[i].category[loop].category_detail.parent_id == this.select_category) {
                continue_loop = 1;
                break;
              }
            }
          }

          if (continue_loop == 0) {
            continue;
          }
        } //console.log("123");


