/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = ({
  data: function data() {
    return {
      showdropdown: false,
      username: ""
    };
  },
  methods: {
    logOut: function logOut() {
      var _this = this;

      this.$parent.loading = true;
      var page_url = "/api/admin/logout";
      axios.post(page_url, {}, this.token).then(function (res) {
        _this.orders = res.data.data;
        setTimeout(function () {
          _this.$router.push("/admin/login");
        }, 1000);
      });
    },
    setBurgerMenu: function setBurgerMenu() {
      var classList = document.body.classList.value.split(" "); //console.log(classList);

      if (classList.indexOf("aside-minimize") === -1) {
        document.body.classList.add("aside-minimize");
        document.getElementById("tc_aside").classList.add("aside-on");
        document.getElementById("aside-overlay").classList.add("active");
      } else {
        document.body.classList.remove("aside-minimize");
        document.getElementById("tc_aside").classList.remove("aside-on");
        document.getElementById("aside-overlay").classList.remove("active");
      }

      this.$emit("setBurgerMenu");
    },
    showDropDown: function showDropDown() {
      this.showdropdown = !this.showdropdown;
    }
  },
  mounted: function mounted() {
    var token = localStorage.getItem("token");
    this.token = {
      headers: {
        Authorization: "Bearer ".concat(token)
      }
    }; //console.log(localStorage.getItem("name"));

    if (localStorage.getItem("name")) {
      this.username = localStorage.getItem("name");
    }
  }
});

